export {
  CANONICAL_JSON_PROFILE,
  JSON_RESOURCE_ENVELOPE,
  UNBOUNDED_JSON_ENVELOPE,
  admitCanonicalJson,
  canonicalizeJson,
  canonicalJson,
} from "../scripts/canonical-json.mjs";
export { assertCanonicalJson } from "../scripts/assert-canonical-json.mjs";
export { isCanonicalJson } from "../scripts/is-canonical-json.mjs";
export { parseJsonValue } from "../scripts/parse-json-value.mjs";
export { isJsonValue } from "../scripts/is-json-value.mjs";
export { requireJsonValue } from "../scripts/require-json-value.mjs";
export { assertNonemptyString } from "../scripts/assert-nonempty-string.mjs";
export { isJsonRecord } from "../scripts/is-json-record.mjs";
export { projectJsonRecordKeys } from "../scripts/project-json-record-keys.mjs";
export { isJsonText } from "../scripts/is-json-text.mjs";
export { writeJsonText } from "../scripts/write-json-text.mjs";
export { encodeJsonByteCarrier } from "../scripts/encode-json-byte-carrier.mjs";
export { decodeJsonByteCarrier } from "../scripts/decode-json-byte-carrier.mjs";
export { freezeJson } from "../scripts/freeze-json.mjs";
export { parseJson } from "../scripts/parse-json.mjs";
export { formCloudEvent } from "../scripts/form-cloudevent.mjs";
export { validateCloudEvent } from "../scripts/validate-cloudevent.mjs";
export { admitJsonType } from "../scripts/admit-json-type.mjs";
export { readJsonField } from "../scripts/read-json-field.mjs";
export { isObjectRecord } from "../scripts/is-object-record.mjs";
export {
  canonicalJson as canonical,
  canonicalJson as canonicalChecked,
} from "../scripts/canonical-json.mjs";
export { parseJsonValue as parse } from "../scripts/parse-json-value.mjs";
export { jsonResource } from "../scripts/json-resource.mjs";
export { resolveJsonPointer } from "../scripts/resolve-json-pointer.mjs";

/**
 * MetroPlat artifacts: bounded RFC 8785 JSON named by its semantic content
 * address under one object kind. Canonical JSON is the JSON section's codec;
 * the name is SEN identity. Refusals are TypeErrors carrying `code` and `path`.
 */
import { JSON_RESOURCE_ENVELOPE, admitCanonicalJson, canonicalizeJson } from "@red-cup-engineering/json-services-section";
import { isNiUri } from "@red-cup-engineering/uri-services-section/ni-uri";
import { semanticIdOf } from "@red-cup-engineering/computer-code-engineering-services-section/semiotic-expression-notation/semantic-content-identity";

export const ARTIFACT_KIND = "metroplat.artifact";

/** The semantic id of one JSON value as a MetroPlat artifact. */
export const artifactId = semanticIdOf(ARTIFACT_KIND);

function refusal(code, path, message) {
  const error = new TypeError(`${code} at ${path}: ${message}`);
  error.code = code;
  error.path = path;
  return error;
}

/** Whether a string is an artifact reference. */
export function isArtifactRef(reference) {
  return isNiUri(reference);
}

/** Canonicalize a runtime value within the resource envelope and name it. */
export function addressArtifact(value) {
  const canonical = canonicalizeJson(value, JSON_RESOURCE_ENVELOPE);
  return Object.freeze({ ref: artifactId(canonical.value), canonical });
}

/** Admit JSON source text strictly and name the value it denotes. */
export function admitArtifact(source) {
  const canonical = admitCanonicalJson(source, JSON_RESOURCE_ENVELOPE);
  return Object.freeze({ ref: artifactId(canonical.value), canonical });
}

/** Admit source text and require that it is the artifact `reference` names. */
export function verifyArtifact(reference, source) {
  if (!isArtifactRef(reference)) throw refusal("reference-syntax", "$", "artifact reference must be one RFC 6920 SHA-256 ni URI");
  const artifact = admitArtifact(source);
  if (artifact.ref !== reference) throw refusal("digest-mismatch", "$", `artifact names ${artifact.ref}, not ${reference}`);
  return artifact;
}

export {
  addressSiteConstitution,
  INITIAL_SITE_CONSTITUTION,
  validateSiteConstitution,
} from "./site.mjs";
export {
  addressTextDocument,
  TEXT_DOCUMENT_BRANCH_WIDTH,
  TEXT_DOCUMENT_LEAF_BYTES,
} from "./text-document.mjs";
export {
  addressPrimitiveArticulation,
  admitPrimitiveArticulation,
} from "./primitive-articulation.mjs";

import { addressPrimitiveArticulation, addressSiteConstitution, INITIAL_SITE_CONSTITUTION, isArtifactRef, verifyArtifact } from "../identity/index.mjs";
import { canonicalizeJson, JSON_RESOURCE_ENVELOPE } from "@red-cup-engineering/json-services-section";
import {
  isCausalWitness,
  causalObstruction,
  causalWitness,

} from "./judgment.mjs";
import { causalGraphHasCycle } from "./causal-graph.mjs";
import {
  INITIAL_CAUSAL_RESOURCE_ENVELOPE,
  validateAddressedWitnessCore,

} from "./witness.mjs";

/** The causal dependency facts needed to judge one witness. Filesystem
 * admission implements this view from exact source artifacts and its derived
 * admission indexes; the in-memory substrate implements it from its maps. */

/** Run one identity step; a refusal comes back as `{ error }`. */
function attempt(step) {
  try {
    return { value: step() };
  } catch (error) {
    return { error };
  }
}

function sorted(values) {
  return Object.freeze([...values].sort());
}

function snapshotRetainedObstructions(input) {
  try {
    if (!Array.isArray(input) || Object.getPrototypeOf(input) !== Array.prototype) return undefined;
    const keys = Reflect.ownKeys(input);
    const lengthDescriptor = Object.getOwnPropertyDescriptor(input, "length");
    if (lengthDescriptor === undefined || !("value" in lengthDescriptor)) return undefined;
    const length = lengthDescriptor.value;
    if (!Number.isSafeInteger(length) || length < 0 || keys.length !== length + 1) return undefined;
    const values = new Map();
    for (const key of keys) {
      if (key === "length") continue;
      if (typeof key !== "string" || !/^(?:0|[1-9][0-9]*)$/u.test(key)) return undefined;
      const index = Number(key);
      if (!Number.isSafeInteger(index) || index >= length) return undefined;
      const descriptor = Object.getOwnPropertyDescriptor(input, key);
      if (descriptor === undefined || !("value" in descriptor)) return undefined;
      values.set(index, descriptor.value);
    }
    const records = [];
    for (let index = 0; index < length; index += 1) {
      if (!values.has(index)) return undefined;
      const canonical = canonicalizeJson(values.get(index), JSON_RESOURCE_ENVELOPE);
      const record = canonical.value;
      if (record === null || Array.isArray(record) || typeof record !== "object") return undefined;
      const keys = Object.keys(record);
      if (keys.length !== 2 || !Object.hasOwn(record, "event") || !Object.hasOwn(record, "obstruction") || !isArtifactRef(record.event)) return undefined;
      records.push({ record, text: canonicalizeJson(record.obstruction, JSON_RESOURCE_ENVELOPE).text });
    }
    records.sort((left, right) => left.record.event < right.record.event ? -1
      : left.record.event > right.record.event ? 1
        : left.text < right.text ? -1 : left.text > right.text ? 1 : 0);
    const unique = [];
    let previous;
    for (const item of records) {
      if (previous !== undefined && previous.record.event === item.record.event && previous.text === item.text) continue;
      unique.push(item.record);
      previous = item;
    }
    return Object.freeze(unique);
  } catch {
    return undefined;
  }
}

function recordKind(artifact) {
  const value = artifact.canonical.value;
  if (value === null || Array.isArray(value) || typeof value !== "object") return undefined;
  const record = value;
  return typeof record.kind === "string" ? record.kind : undefined;
}

/** Judge one witness against an already-settled causal cut. This is the one
 * dependency rule used by both whole-source reconstruction and incremental
 * filesystem admission. A persisted admitted cause is a fixed predecessor;
 * missing and quarantined causes remain obstructions-to-readiness, while a
 * structurally blocked cause propagates its obstruction. */
export function evaluateWitnessDependencies(
  witness,
  view,
  site = INITIAL_SITE_CONSTITUTION,
) {
  const core = witness.core;
  const missing = new Set();
  const articulationArtifact = view.artifact(core.articulation);
  let articulation;
  if (articulationArtifact === undefined) {
    missing.add(core.articulation);
  } else {
    const validated = attempt(() => addressPrimitiveArticulation(articulationArtifact.canonical.value, site));
    if (validated.error !== undefined || validated.value.ref !== core.articulation) {
      return {
        missing: Object.freeze([]),
        obstruction: causalObstruction("articulation-invalid", "$.articulation", "articulation dependency is not a valid primitive articulation", [core.articulation]),
      };
    }
    articulation = validated.value.articulation;
  }
  if (articulation !== undefined) {
    if (view.artifact(articulation.token) === undefined) missing.add(articulation.token);
    if (view.artifact(articulation.claim) === undefined) missing.add(articulation.claim);
  }
  for (const artifact of core.referencedArtifacts) {
    if (view.artifact(artifact) === undefined) missing.add(artifact);
  }
  for (const cause of core.causes) {
    const state = view.witnessState(cause);
    if (state === "admitted") continue;
    if (state === "blocked") {
      return {
        missing: Object.freeze([]),
        obstruction: causalObstruction("cause-blocked", "$.causes", "a causal dependency is structurally blocked", [cause]),
      };
    }
    if (state === "quarantined") {
      missing.add(cause);
      continue;
    }
    if (view.artifact(cause) !== undefined) {
      return {
        missing: Object.freeze([]),
        obstruction: causalObstruction("cause-not-witness", "$.causes", "a causal dependency address contains no valid WitnessCore", [cause]),
      };
    }
    missing.add(cause);
  }
  return { missing: sorted(missing) };
}

export class CausalSubstrate {
 site;
 causalEnvelope;

 artifactsByRef = new Map();
 coresByRef = new Map();
 quarantinedRefs = new Set();
 admittedRefs = new Set();
 blockedByRef = new Map();
 missingByRef = new Map();
 retainedObstructionRecords = Object.freeze([]);
 retainedObstructionRefs = new Set();

 constructor(
    site,
    causalEnvelope = INITIAL_CAUSAL_RESOURCE_ENVELOPE,
  ) {
    this.site = site;
    this.causalEnvelope = Object.freeze({ ...causalEnvelope });
  }

  static fromMountedSite(
    site,
    causalEnvelope = INITIAL_CAUSAL_RESOURCE_ENVELOPE,
  ) {
    return new CausalSubstrate(site, causalEnvelope);
  }

  receive(reference, source) {
    const verified = attempt(() => verifyArtifact(reference, source));
    if (verified.error !== undefined) {
      return causalObstruction("artifact-invalid", verified.error.path ?? "$", verified.error.message, typeof reference === "string" ? [reference] : []);
    }
    const artifact = verified.value;
    const existing = this.artifactsByRef.get(artifact.ref);
    if (existing !== undefined) {
      if (existing.canonical.text !== artifact.canonical.text) {
        return causalObstruction("address-collision", "$", "one ArtifactRef was observed with different canonical bytes", [artifact.ref]);
      }
      const changes = this.promoteAvailable();
      return causalWitness(this.receipt(artifact.ref, "existing", this.coresByRef.has(artifact.ref), changes));
    }

    let witness;
    if (recordKind(artifact) === "metroplat.witness-core") {
      const validated = validateAddressedWitnessCore(
        artifact.canonical,
        this.site.constitution,
        this.causalEnvelope,
      );
      if (!isCausalWitness(validated)) return validated;
      witness = validated.value;
      if (witness.ref !== artifact.ref) {
        return causalObstruction("artifact-invalid", "$", "WitnessRef does not equal its canonical artifact address", [artifact.ref]);
      }
      if (this.wouldCreateCycle(witness.ref, witness.core)) {
        return causalObstruction("causal-cycle", "$.causes", "WitnessCore would introduce a causal cycle", [witness.ref, ...witness.core.causes]);
      }
    }

    this.artifactsByRef.set(artifact.ref, artifact);
    if (witness !== undefined) {
      this.coresByRef.set(witness.ref, witness);
      if (!this.retainedObstructionRefs.has(witness.ref)) this.quarantinedRefs.add(witness.ref);
    }
    const changes = this.promoteAvailable();
    return causalWitness(this.receipt(artifact.ref, "stored", witness !== undefined, changes));
  }

  /**
   * Receive one finite immutable source-set union, then compute dependency
   * promotion once over the union.
   *
   * `rebuildCausalSubstrate` already promises reception-order-independent
   * reconstruction. Running `promoteAvailable` after every artifact does not
   * strengthen that result: it repeatedly derives intermediate closures that
   * no caller observes. This operation validates every source and the complete
   * causal graph before mutating the substrate, joins the sources, and derives
   * the one least promotion closure the rebuilt snapshot exposes.
   */
  receiveSourceSet(sources) {
    const stagedArtifacts = new Map();
    const stagedCores = new Map();

    for (const source of sources) {
      const verified = attempt(() => verifyArtifact(source.ref, source.canonicalText));
      if (verified.error !== undefined) {
        return causalObstruction("artifact-invalid", verified.error.path ?? "$", verified.error.message, [source.ref]);
      }
      const artifact = verified.value;
      const existing = stagedArtifacts.get(artifact.ref) ?? this.artifactsByRef.get(artifact.ref);
      if (existing !== undefined) {
        if (existing.canonical.text !== artifact.canonical.text) {
          return causalObstruction("address-collision", "$", "one ArtifactRef was observed with different canonical bytes", [artifact.ref]);
        }
        continue;
      }

      stagedArtifacts.set(artifact.ref, artifact);
      if (recordKind(artifact) !== "metroplat.witness-core") continue;
      const validated = validateAddressedWitnessCore(
        artifact.canonical,
        this.site.constitution,
        this.causalEnvelope,
      );
      if (!isCausalWitness(validated)) return validated;
      const witness = validated.value;
      if (witness.ref !== artifact.ref) {
        return causalObstruction("artifact-invalid", "$", "WitnessRef does not equal its canonical artifact address", [artifact.ref]);
      }
      stagedCores.set(witness.ref, witness);
    }

    const causalGraph = [
      ...this.coresByRef.values(),
      ...stagedCores.values(),
    ].map((witness) => ({ ref: witness.ref, causes: witness.core.causes }));
    if (causalGraphHasCycle(causalGraph)) {
      return causalObstruction(
        "causal-cycle",
        "$.causes",
        "WitnessCore source-set union would introduce a causal cycle",
        sorted(stagedCores.keys()),
      );
    }

    for (const [ref, artifact] of stagedArtifacts) this.artifactsByRef.set(ref, artifact);
    for (const [ref, witness] of stagedCores) {
      this.coresByRef.set(ref, witness);
      if (!this.retainedObstructionRefs.has(ref)) this.quarantinedRefs.add(ref);
    }
    this.promoteAvailable();
    return causalWitness(this);
  }

  artifact(reference) {
    return this.artifactsByRef.get(reference);
  }

  witness(reference) {
    return this.coresByRef.get(reference);
  }

  witnessState(reference) {
    if (this.blockedByRef.has(reference)) return "blocked";
    if (this.admittedRefs.has(reference)) return "admitted";
    if (this.quarantinedRefs.has(reference)) return "quarantined";
    return "not-witness";
  }

  missingDependencies(reference) {
    return this.missingByRef.get(reference) ?? Object.freeze([]);
  }

  obstruction(reference) {
    return this.blockedByRef.get(reference);
  }

  admittedWitnessRefs() {
    return sorted(this.admittedRefs);
  }

  sourceArtifacts() {
    return Object.freeze(sorted(this.artifactsByRef.keys()).map((ref) => Object.freeze({
      ref,
      canonicalText: this.artifactsByRef.get(ref).canonical.text,
    })));
  }

  retainedObstructions() {
    return this.retainedObstructionRecords;
  }

  snapshot() {
    return Object.freeze({
      kind: "metroplat.journal.substrate-snapshot",
      site: this.site.ref,
      artifacts: this.sourceArtifacts(),
      witnesses: sorted(this.coresByRef.keys()),
      admitted: sorted(this.admittedRefs),
      quarantined: sorted(this.quarantinedRefs),
      blocked: sorted(this.blockedByRef.keys()),
      retainedObstructions: this.retainedObstructions(),
    });
  }

 receipt(
    ref,
    disposition,
    isWitness,
    changes,
  ) {
    const witnessRef = ref;
    return Object.freeze({
      kind: "metroplat.journal.reception",
      ref,
      disposition,
      classification: isWitness ? "witness" : "artifact",
      witnessState: isWitness ? this.witnessState(witnessRef) : "not-witness",
      missing: isWitness ? this.missingDependencies(witnessRef) : Object.freeze([]),
      promoted: changes.promoted,
      blocked: changes.blocked,
    });
  }

 wouldCreateCycle(ref, core) {
    return causalGraphHasCycle([
      ...[...this.coresByRef.values()].map((witness) => ({ ref: witness.ref, causes: witness.core.causes })),
      { ref, causes: core.causes },
    ]);
  }

 promoteAvailable() {
    const promoted = new Set();
    const blocked = new Set();
    let changed = true;
    while (changed) {
      changed = false;
      for (const ref of sorted(this.quarantinedRefs)) {
        const evaluation = this.evaluateDependencies(ref);
        if (evaluation.obstruction !== undefined) {
          this.quarantinedRefs.delete(ref);
          this.missingByRef.delete(ref);
          this.blockedByRef.set(ref, evaluation.obstruction);
          blocked.add(ref);
          changed = true;
          continue;
        }
        this.missingByRef.set(ref, evaluation.missing);
        if (evaluation.missing.length === 0) {
          this.quarantinedRefs.delete(ref);
          this.missingByRef.delete(ref);
          this.admittedRefs.add(ref);
          promoted.add(ref);
          changed = true;
        }
      }
    }
    return Object.freeze({ promoted: sorted(promoted), blocked: sorted(blocked) });
  }

 evaluateDependencies(ref) {
    const witness = this.coresByRef.get(ref);
    return evaluateWitnessDependencies(witness, {
      artifact: (reference) => this.artifactsByRef.get(reference),
      witnessState: (reference) => this.witnessState(reference),
    }, this.site.constitution);
  }
}

export function createCausalSubstrate(
  site = INITIAL_SITE_CONSTITUTION,
  causalEnvelope = INITIAL_CAUSAL_RESOURCE_ENVELOPE,
) {
  const addressed = attempt(() => addressSiteConstitution(site));
  return addressed.error === undefined
    ? causalWitness(CausalSubstrate.fromMountedSite(addressed.value, causalEnvelope))
    : causalObstruction("site-mismatch", "$", addressed.error.message);
}

export function rebuildCausalSubstrate(
  sources,
  site = INITIAL_SITE_CONSTITUTION,
  causalEnvelope = INITIAL_CAUSAL_RESOURCE_ENVELOPE,
  retainedObstructions = [],
) {
  const retained = snapshotRetainedObstructions(retainedObstructions);
  if (retained === undefined) {
    return causalObstruction("retained-obstruction-invalid", "$.retainedObstructions", "retained obstruction input is invalid");
  }
  const created = createCausalSubstrate(site, causalEnvelope);
  if (!isCausalWitness(created)) return created;
  const substrate = created.value;
  substrate.retainedObstructionRecords = retained;
  for (const record of retained) {
    substrate.retainedObstructionRefs.add(record.event);
    substrate.blockedByRef.set(record.event, causalObstruction(
      "retained-block",
      "$",
      "a retained journal admission decision blocks this witness",
      [record.event],
    ));
  }
  return substrate.receiveSourceSet(sources);
}

/** Causal reception, admission, and frontier judgments. */

export function causalWitness(value) {
  return Object.freeze({ kind: "metroplat.causal:witness", value });
}

export function causalObstruction(
  code,
  path,
  message,
  relatedRefs = Object.freeze([]),
) {
  return Object.freeze({
    kind: "metroplat.causal:obstruction",
    code,
    path,
    message,
    relatedRefs: Object.freeze([...relatedRefs].sort()),
  });
}

export function isCausalWitness(judgment) {
  return judgment.kind === "metroplat.causal:witness";
}

/**
 * src/journal/causal-graph - the causal audit graph.
 *
 * Every journal event carries `causes`: the ids of the events that had to
 * exist before it. Those edges induce one graph over the whole journal. This
 * module is that graph's single home: build it from events, walk it, order
 * it. It is pure — no filesystem, no store. The store enforces acyclicity at
 * admission; this module lets everything above the store read the same
 * structure by one name.
 *
 * An edge id in `causes` may reference an event outside the given slice
 * (earlier history not loaded). Such edges are kept and reported as
 * `externalCauses` rather than dropped, so a partial read never silently
 * rewrites history's shape.
 *
 * The causal order is the transitive closure of `causes` (MetroPlat architecture, 5.6); this module
 * computes it from the cause maps themselves, as the journal's own law beneath metrologic.
 */

/** Detect a cycle without inventing an order for spacelike witnesses. */
export function causalGraphHasCycle(entries) {
  const refs = new Set(entries.map((entry) => entry.ref));
  const pending = new Map();
  const effects = new Map();
  for (const ref of refs) pending.set(ref, 0);
  for (const entry of entries) {
    for (const cause of new Set(entry.causes)) {
      if (!refs.has(cause)) continue;
      pending.set(entry.ref, pending.get(entry.ref) + 1);
      effects.set(cause, [...(effects.get(cause) ?? []), entry.ref]);
    }
  }
  const ready = [...pending].filter(([, count]) => count === 0).map(([ref]) => ref);
  let placed = 0;
  while (ready.length > 0) {
    const ref = ready.pop();
    placed += 1;
    for (const effect of effects.get(ref) ?? []) {
      const remaining = pending.get(effect) - 1;
      pending.set(effect, remaining);
      if (remaining === 0) ready.push(effect);
    }
  }
  return placed !== refs.size;
}

export function causalGraphOf(events) {
  const byId = new Map();
  for (const event of events) byId.set(event.id, event);
  const parents = new Map();
  const children = new Map();
  const externalCauses = new Set();
  for (const event of byId.values()) {
    const present = [];
    for (const cause of event.core.causes) {
      if (!byId.has(cause)) {
        externalCauses.add(cause);
        continue;
      }
      present.push(cause);
      const siblings = children.get(cause);
      if (siblings === undefined) children.set(cause, [event.id]);
      else siblings.push(event.id);
    }
    parents.set(event.id, Object.freeze(present));
  }
  const roots = [];
  const heads = [];
  for (const id of byId.keys()) {
    if ((parents.get(id) ?? []).length === 0) roots.push(id);
    if ((children.get(id) ?? []).length === 0) heads.push(id);
  }
  const frozenChildren = new Map();
  for (const [id, list] of children) frozenChildren.set(id, Object.freeze(list));
  return Object.freeze({
    events: byId,
    parents,
    children: frozenChildren,
    externalCauses,
    roots: Object.freeze(roots),
    heads: Object.freeze(heads),
  });
}

/** Every id reachable from `start` along one of the graph's edge maps, `start` itself excluded. */
function reachableAlong(edges, start) {
  const seen = new Set();
  const frontier = [start];
  while (frontier.length > 0) {
    for (const next of edges.get(frontier.pop()) ?? []) {
      if (seen.has(next)) continue;
      seen.add(next);
      frontier.push(next);
    }
  }
  return seen;
}

/** Ids of every event reachable from `id` by following causes, oldest-first. */
export function ancestorsOf(graph, id) {
  const seen = reachableAlong(graph.parents, id);
  return Object.freeze(topologicalOrder(graph).map((event) => event.id).filter((eventId) => seen.has(eventId)));
}

/** Ids of every event reachable from `id` by followed-by edges, oldest-first. */
export function descendantsOf(graph, id) {
  const seen = reachableAlong(graph.children, id);
  return Object.freeze(topologicalOrder(graph).map((event) => event.id).filter((eventId) => seen.has(eventId)));
}

/**
 * All slice events in an order where every cause precedes its effects.
 * Spacelike ties break only by exact event id, so wall time never becomes a
 * causal order. Throws if the slice contains a causal cycle, which the store
 * refuses at admission — seeing one here means the journal was edited
 * outside the store.
 */
export function topologicalOrder(graph) {
  const pending = new Map();
  for (const [id, list] of graph.parents) pending.set(id, list.length);
  const byId = (a, b) => a < b ? -1 : a > b ? 1 : 0;
  const ready = [...pending.keys()].filter((id) => pending.get(id) === 0).sort(byId);
  const order = [];
  while (ready.length > 0) {
    const id = ready.shift();
    order.push(graph.events.get(id));
    const unlocked = [];
    for (const child of graph.children.get(id) ?? []) {
      const remaining = pending.get(child) - 1;
      pending.set(child, remaining);
      if (remaining === 0) unlocked.push(child);
    }
    unlocked.sort(byId);
    let at = 0;
    for (const next of unlocked) {
      while (at < ready.length && byId(ready[at], next) < 0) at += 1;
      ready.splice(at, 0, next);
    }
  }
  if (order.length !== graph.events.size) {
    throw new TypeError("causal event graph contains a cycle; the journal was modified outside the store");
  }
  return Object.freeze(order);
}

/** The initial bare site identity and its mounted profiles. */
import { JSON_RESOURCE_ENVELOPE, canonicalizeJson } from "@red-cup-engineering/json-services-section";
import { addressArtifact } from "./index.mjs";

export const MARK_AND_ARTICULATION_PROFILE_ID = "metroplat-mark-articulation-1";
export const CAUSAL_PROFILE_ID = "metroplat-causal-witness-1";
export const FOUR_PROFILE_ID = "obsmetrologia-four-1";
export const NO_MEASUREMENT_PROFILE_ID = "metroplat-no-measurement-1";
export const NO_SEMANTIC_APPRAISAL_PROFILE_ID = "metroplat-no-semantic-appraisal-1";
export const RESOURCE_ENVELOPE_PROFILE_ID = "metroplat-resource-envelope-1";

const emptyProfileList = () => Object.freeze([]);

export const INITIAL_SITE_CONSTITUTION = Object.freeze({
  kind: "metroplat.site-constitution",
  version: 1,
  markAndArticulationProfile: MARK_AND_ARTICULATION_PROFILE_ID,
  causalProfile: CAUSAL_PROFILE_ID,
  FOURProfile: FOUR_PROFILE_ID,
  languageAndTypingProfiles: emptyProfileList(),
  measurementKernelProfile: NO_MEASUREMENT_PROFILE_ID,
  appraisalKernelProfile: NO_SEMANTIC_APPRAISAL_PROFILE_ID,
  coordinationAndReconciliationProfiles: emptyProfileList(),
  identityAttestationProfiles: emptyProfileList(),
  resourceEnvelopeProfile: RESOURCE_ENVELOPE_PROFILE_ID,
  formalCorrespondenceRefs: emptyProfileList(),
});

const siteKeys = Object.freeze(Object.keys(INITIAL_SITE_CONSTITUTION).sort());

function refusal(message) {
  const error = new TypeError(`site-constitution at $: ${message}`);
  error.code = "site-constitution";
  error.path = "$";
  return error;
}

function exactKeys(value, expected) {
  const actual = Object.keys(value).sort();
  return actual.length === expected.length && actual.every((key, index) => key === expected[index]);
}

/** Admit a site constitution; only the mounted articulation-only profile is admitted. */
export function validateSiteConstitution(value) {
  const record = canonicalizeJson(value, JSON_RESOURCE_ENVELOPE).value;
  if (record === null || Array.isArray(record) || typeof record !== "object") throw refusal("site constitution must be an object");
  if (!exactKeys(record, siteKeys)) throw refusal("site constitution has missing or additional properties");
  const empty = (field) => Array.isArray(record[field]) && record[field].length === 0;
  if (
    record.kind !== INITIAL_SITE_CONSTITUTION.kind ||
    record.version !== INITIAL_SITE_CONSTITUTION.version ||
    record.markAndArticulationProfile !== MARK_AND_ARTICULATION_PROFILE_ID ||
    record.causalProfile !== CAUSAL_PROFILE_ID ||
    record.FOURProfile !== FOUR_PROFILE_ID ||
    record.measurementKernelProfile !== NO_MEASUREMENT_PROFILE_ID ||
    record.appraisalKernelProfile !== NO_SEMANTIC_APPRAISAL_PROFILE_ID ||
    record.resourceEnvelopeProfile !== RESOURCE_ENVELOPE_PROFILE_ID ||
    !empty("languageAndTypingProfiles") ||
    !empty("coordinationAndReconciliationProfiles") ||
    !empty("identityAttestationProfiles") ||
    !empty("formalCorrespondenceRefs")
  ) throw refusal("constitution is not the mounted articulation-only site profile");
  return INITIAL_SITE_CONSTITUTION;
}

/** The site constitution as an addressed artifact. */
export function addressSiteConstitution(value = INITIAL_SITE_CONSTITUTION) {
  const constitution = validateSiteConstitution(value);
  return Object.freeze({ ...addressArtifact(constitution), constitution });
}

/**
 * @packageDocumentation
 * Identity admission for the primitive token/claim articulation carrier.
 *
 * @metroplatSubject identity
 */
import { addressArtifact, admitArtifact, isArtifactRef } from "./index.mjs";
import { INITIAL_SITE_CONSTITUTION, validateSiteConstitution } from "./site.mjs";

const articulationKeys = Object.freeze(["claim", "kind", "token", "version"]);

function refusal(path, message) {
  const error = new TypeError(`primitive-articulation at ${path}: ${message}`);
  error.code = "primitive-articulation";
  error.path = path;
  return error;
}

function exactKeys(value) {
  const actual = Object.keys(value).sort();
  return actual.length === articulationKeys.length && actual.every((key, index) => key === articulationKeys[index]);
}

function validateArticulation(record, site) {
  validateSiteConstitution(site);
  if (record === null || Array.isArray(record) || typeof record !== "object") throw refusal("$", "primitive articulation must be an object");
  if (!exactKeys(record)) throw refusal("$", "primitive articulation has missing or additional properties");
  if (record.kind !== "metroplat.primitive-articulation" || record.version !== 1) {
    throw refusal("$", "unsupported primitive articulation kind or version");
  }
  if (!isArtifactRef(record.token)) throw refusal("$.token", "token must be an artifact reference");
  if (!isArtifactRef(record.claim)) throw refusal("$.claim", "claim must be an artifact reference");
  return Object.freeze({ kind: "metroplat.primitive-articulation", version: 1, token: record.token, claim: record.claim });
}

/** Address a runtime primitive articulation. */
export function addressPrimitiveArticulation(value, site = INITIAL_SITE_CONSTITUTION) {
  const addressed = addressArtifact(value);
  return Object.freeze({ ...addressed, articulation: validateArticulation(addressed.canonical.value, site) });
}

/** Admit a primitive articulation from JSON source. */
export function admitPrimitiveArticulation(source, site = INITIAL_SITE_CONSTITUTION) {
  const admitted = admitArtifact(source);
  return Object.freeze({ ...admitted, articulation: validateArticulation(admitted.canonical.value, site) });
}

#!/usr/bin/env node
/** RFC 8785 (JCS) canonical JSON: strict admission of runtime values and JSON
 * text, optional resource bounds, and the one canonical serialization. */
export const CANONICAL_JSON_PROFILE = "RFC8785";
export const inputSchema = {};
export const outputSchema = { type: "string" };

/** No bounds: the default for values the caller already holds. */
export const UNBOUNDED_JSON_ENVELOPE = Object.freeze({
  maxSourceBytes: Infinity,
  maxCanonicalBytes: Infinity,
  maxDepth: Infinity,
  maxNodes: Infinity,
  maxObjectMembers: Infinity,
  maxArrayLength: Infinity,
  maxStringBytes: Infinity,
  maxKeyBytes: Infinity,
});

/** Bounds for admitting untrusted JSON: 1 MiB, depth 64, 100k nodes. */
export const JSON_RESOURCE_ENVELOPE = Object.freeze({
  maxSourceBytes: 1_048_576,
  maxCanonicalBytes: 1_048_576,
  maxDepth: 64,
  maxNodes: 100_000,
  maxObjectMembers: 4_096,
  maxArrayLength: 65_536,
  maxStringBytes: 262_144,
  maxKeyBytes: 1_024,
});

const utf8Encoder = new TextEncoder();
const numberGrammar = /^-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?$/u;

function byteLength(value) {
  return utf8Encoder.encode(value).byteLength;
}

function pathText(path) {
  const parts = [];
  let base = "$";
  for (let node = path; node !== null && typeof node === "object"; node = node.parent) {
    parts.push(node);
  }
  if (typeof path === "string") base = path;
  let text = base;
  for (let index = parts.length - 1; index >= 0; index -= 1) {
    const part = parts[index];
    text += part.kind === "index" ? `[${part.value}]` : `.${part.value}`;
  }
  return text;
}

function propertyPath(path, key) {
  return { parent: path, kind: "property", value: key };
}

function indexPath(path, index) {
  return { parent: path, kind: "index", value: index };
}

function fail(code, path, message) {
  const renderedPath = pathText(path);
  const error = new TypeError(`${code} at ${renderedPath}: ${message}`);
  error.code = code;
  error.path = renderedPath;
  throw error;
}

function assertUnicodeScalars(value, path) {
  for (let index = 0; index < value.length; index += 1) {
    const unit = value.charCodeAt(index);
    if (unit >= 0xd800 && unit <= 0xdbff) {
      const next = value.charCodeAt(index + 1);
      if (!(next >= 0xdc00 && next <= 0xdfff)) {
        fail("unicode-scalar", path, "must not contain a lone Unicode surrogate (high)");
      }
      index += 1;
    } else if (unit >= 0xdc00 && unit <= 0xdfff) {
      fail("unicode-scalar", path, "must not contain a lone Unicode surrogate (low)");
    }
  }
}

function stringText(value, path, limit, code) {
  assertUnicodeScalars(value, path);
  if (byteLength(value) > limit) fail(code, path, `UTF-8 string exceeds ${limit} bytes`);
  return JSON.stringify(value);
}

function chargeCanonical(state, amount, path) {
  state.canonicalBytes += amount;
  if (state.canonicalBytes > state.envelope.maxCanonicalBytes) {
    fail("canonical-limit", path, `canonical JSON exceeds ${state.envelope.maxCanonicalBytes} bytes`);
  }
}

function projectValue(value, path, depth, state) {
  const tokens = [];
  const frames = [{ source: value, path, depth, entered: false }];
  let result;

  while (frames.length > 0) {
    const frame = frames[frames.length - 1];
    if (!frame.entered) {
      frame.entered = true;
      state.nodes += 1;
      if (state.nodes > state.envelope.maxNodes) {
        fail("node-limit", frame.path, `JSON value exceeds ${state.envelope.maxNodes} nodes`);
      }
      const item = frame.source;
      if (item === null) {
        chargeCanonical(state, 4, frame.path);
        tokens.push("null");
        result = null;
        frames.pop();
        continue;
      }
      if (typeof item === "boolean") {
        const text = item ? "true" : "false";
        chargeCanonical(state, text.length, frame.path);
        tokens.push(text);
        result = item;
        frames.pop();
        continue;
      }
      if (typeof item === "string") {
        const text = stringText(item, frame.path, state.envelope.maxStringBytes, "string-limit");
        chargeCanonical(state, byteLength(text), frame.path);
        tokens.push(text);
        result = item;
        frames.pop();
        continue;
      }
      if (typeof item === "number") {
        if (!Number.isFinite(item)) fail("invalid-json-value", frame.path, "JCS admits only finite IEEE-754 numbers");
        const text = JSON.stringify(item);
        chargeCanonical(state, byteLength(text), frame.path);
        tokens.push(text);
        result = Object.is(item, -0) ? 0 : item;
        frames.pop();
        continue;
      }
      if (typeof item !== "object") {
        fail("invalid-json-value", frame.path, `unsupported JSON value type: ${typeof item}`);
      }
      if (frame.depth >= state.envelope.maxDepth) {
        fail("depth-limit", frame.path, `JSON nesting exceeds depth ${state.envelope.maxDepth}`);
      }
      if (state.active.has(item)) fail("invalid-json-value", frame.path, "must not contain a cycle");
      state.active.add(item);
      frame.container = item;
      frame.index = 0;

      if (Array.isArray(item)) {
        if (item.length > state.envelope.maxArrayLength) {
          fail("array-length-limit", frame.path, `array exceeds ${state.envelope.maxArrayLength} elements`);
        }
        const ownKeys = Reflect.ownKeys(item);
        if (ownKeys.some((key) => key !== "length" && (typeof key !== "string" || !/^(?:0|[1-9][0-9]*)$/u.test(key) || Number(key) >= item.length))) {
          fail("invalid-json-value", frame.path, "arrays may not carry symbol or non-index properties");
        }
        chargeCanonical(state, 2 + Math.max(0, item.length - 1), frame.path);
        tokens.push("[");
        frame.array = true;
        frame.carried = [];
        frame.length = item.length;
      } else {
        if (Object.getPrototypeOf(item) !== Object.prototype) {
          fail("invalid-json-value", frame.path, "only ordinary JSON objects with Object.prototype are admitted");
        }
        const keys = Reflect.ownKeys(item);
        if (keys.some((key) => typeof key !== "string")) {
          fail("invalid-json-value", frame.path, "symbol properties are outside the JSON data model");
        }
        if (keys.length > state.envelope.maxObjectMembers) {
          fail("object-member-limit", frame.path, `object exceeds ${state.envelope.maxObjectMembers} members`);
        }
        frame.keys = keys.sort();
        chargeCanonical(state, 2 + Math.max(0, frame.keys.length - 1) + frame.keys.length, frame.path);
        tokens.push("{");
        frame.carried = {};
        frame.array = false;
      }
      continue;
    }

    const count = frame.array ? frame.length : frame.keys.length;
    if (frame.awaitingChild) {
      if (frame.array) {
        frame.carried.push(result);
      } else {
        Object.defineProperty(frame.carried, frame.key, {
          value: result,
          enumerable: true,
          configurable: false,
          writable: false,
        });
      }
      frame.awaitingChild = false;
      frame.index += 1;
    }
    if (frame.index === count) {
      tokens.push(frame.array ? "]" : "}");
      const carried = Object.freeze(frame.carried);
      state.active.delete(frame.container);
      result = carried;
      frames.pop();
      continue;
    }
    if (frame.index > 0) tokens.push(",");
    let child;
    let childPath;
    if (frame.array) {
      const index = frame.index;
      const descriptor = Object.getOwnPropertyDescriptor(frame.container, String(index));
      childPath = indexPath(frame.path, index);
      if (descriptor === undefined) {
        fail("invalid-json-value", childPath, "sparse arrays are outside the admitted JSON value model");
      }
      if (!("value" in descriptor) || !descriptor.enumerable) {
        fail("invalid-json-value", childPath, "array accessors and non-enumerable elements are outside the JSON data model");
      }
      child = descriptor.value;
    } else {
      const key = frame.keys[frame.index];
      const descriptor = Object.getOwnPropertyDescriptor(frame.container, key);
      childPath = propertyPath(frame.path, key);
      if (descriptor === undefined || !("value" in descriptor) || !descriptor.enumerable) {
        fail("invalid-json-value", childPath, "accessor and non-enumerable properties are outside the JSON data model");
      }
      const keyText = stringText(key, childPath, state.envelope.maxKeyBytes, "key-limit");
      chargeCanonical(state, byteLength(keyText), childPath);
      tokens.push(keyText, ":");
      frame.key = key;
      child = descriptor.value;
    }
    frame.awaitingChild = true;
    frames.push({ source: child, path: childPath, depth: frame.depth + 1, entered: false });
  }

  return { value: result, text: tokens.join("") };
}

class StrictJsonParser {
  index = 0;
  nodes = 0;
  source;
  envelope;
  frames = [];
  completed;

  constructor(source, envelope) {
    this.source = source;
    this.envelope = envelope;
  }

  parse() {
    this.space();
    const value = this.value("$", 0);
    let root = this.frames.length === 0 ? value : undefined;
    while (this.frames.length > 0) {
      const frame = this.frames[this.frames.length - 1];
      if (frame.state === "awaiting") {
        if (frame.array) {
          frame.out.push(this.completed);
        } else {
          Object.defineProperty(frame.out, frame.key, {
            value: this.completed,
            enumerable: true,
            configurable: false,
            writable: false,
          });
        }
        frame.state = "afterValue";
      }

      if (frame.array) {
        if (frame.state === "valueOrClose" && this.take("]")) {
          this.finishFrame();
          continue;
        }
        if (frame.state === "valueOrClose" || frame.state === "value") {
          if (frame.out.length >= this.envelope.maxArrayLength) {
            fail("array-length-limit", frame.path, `array exceeds ${this.envelope.maxArrayLength} elements`);
          }
          const childPath = indexPath(frame.path, frame.out.length);
          frame.state = "awaiting";
          const frameCount = this.frames.length;
          const child = this.value(childPath, frame.depth + 1);
          if (this.frames.length === frameCount) {
            frame.out.push(child);
            frame.state = "afterValue";
          }
          continue;
        }
        this.space();
        if (this.take("]")) {
          this.finishFrame();
          continue;
        }
        if (!this.take(",")) {
          fail("malformed-json", frame.path, `comma or array close expected at UTF-16 offset ${this.index}`);
        }
        this.space();
        frame.state = "value";
        continue;
      }

      if (frame.state === "keyOrClose" && this.take("}")) {
        this.finishFrame();
        continue;
      }
      if (frame.state === "keyOrClose" || frame.state === "key") {
        if (this.source[this.index] !== "\"") {
          fail("malformed-json", frame.path, `object name expected at UTF-16 offset ${this.index}`);
        }
        const key = this.string(frame.path, this.envelope.maxKeyBytes, "key-limit");
        if (frame.names.has(key)) {
          fail("duplicate-key", propertyPath(frame.path, key), `duplicate object name: ${JSON.stringify(key)}`);
        }
        frame.names.add(key);
        frame.members += 1;
        if (frame.members > this.envelope.maxObjectMembers) {
          fail("object-member-limit", frame.path, `object exceeds ${this.envelope.maxObjectMembers} members`);
        }
        this.space();
        const childPath = propertyPath(frame.path, key);
        if (!this.take(":")) {
          fail("malformed-json", childPath, `colon expected at UTF-16 offset ${this.index}`);
        }
        this.space();
        frame.key = key;
        frame.state = "awaiting";
        const frameCount = this.frames.length;
        const child = this.value(childPath, frame.depth + 1);
        if (this.frames.length === frameCount) {
          Object.defineProperty(frame.out, key, {
            value: child,
            enumerable: true,
            configurable: false,
            writable: false,
          });
          frame.state = "afterValue";
        }
        continue;
      }
      this.space();
      if (this.take("}")) {
        this.finishFrame();
        continue;
      }
      if (!this.take(",")) {
        fail("malformed-json", frame.path, `comma or object close expected at UTF-16 offset ${this.index}`);
      }
      this.space();
      frame.state = "key";
    }
    if (this.frames.length === 0 && value === undefined) root = this.completed;
    this.space();
    if (this.index !== this.source.length) fail("malformed-json", "$", `unexpected input at UTF-16 offset ${this.index}`);
    return root;
  }

  finishFrame() {
    const frame = this.frames.pop();
    this.completed = Object.freeze(frame.out);
  }

  value(path, depth) {
    this.nodes += 1;
    if (this.nodes > this.envelope.maxNodes) {
      fail("node-limit", path, `JSON value exceeds ${this.envelope.maxNodes} nodes`);
    }
    const lead = this.source[this.index];
    if (lead === "{" || lead === "[") {
      if (depth >= this.envelope.maxDepth) {
        fail("depth-limit", path, `JSON nesting exceeds depth ${this.envelope.maxDepth}`);
      }
      this.index += 1;
      this.space();
      if (lead === "{") {
        this.frames.push({
          path, depth, array: false, out: {}, names: new Set(), members: 0, state: "keyOrClose",
        });
      } else {
        this.frames.push({ path, depth, array: true, out: [], state: "valueOrClose" });
      }
      return undefined;
    }
    if (lead === "\"") return this.string(path, this.envelope.maxStringBytes, "string-limit");
    if (this.source.startsWith("true", this.index)) return this.literal("true", true);
    if (this.source.startsWith("false", this.index)) return this.literal("false", false);
    if (this.source.startsWith("null", this.index)) return this.literal("null", null);
    return this.number(path);
  }

  literal(token, value) {
    this.index += token.length;
    return value;
  }

  string(path, limit, code) {
    const start = this.index;
    this.index += 1;
    while (this.index < this.source.length) {
      const unit = this.source.charCodeAt(this.index);
      if (unit === 0x22) {
        this.index += 1;
